  h.app.setBoard(el);h.app.state.interact=false;let prevented=0;const before=h.app.state.cfg.weekPx;
  handlers.wheel({ctrlKey:false,deltaY:-10,clientX:300,preventDefault(){prevented++;}});assert.equal(h.app.state.cfg.weekPx,before);
