test('Vertical resize crosses row boundaries but clamps to all rows and preserves undo/save',()=>{
  for(const kind of ['chev','plain'])for(const mode of ['top','bottom']){const {h,it}=heightFixture();it.kind=kind;const before=h.app.snapshot(),bounds=h.app.heightBounds(it);
    h.app.drag={id:it.id,kind,mode,...bounds,x0:0,y0:0,snap:before,moved:false};
    h.app.onMove({clientX:0,clientY:mode==='top'?-10000:10000});const after=h.app.state.items.find(i=>i.id===it.id),box=h.app.trackBox(after);assert.equal(after.row,it.row);
    assert.equal(mode==='top'?box.top:box.bottom,mode==='top'?6:bounds.total-6);assert.ok(mode==='top'?box.localTop<0:box.localTop+box.height>140);assert.ok(h.app.state.rows.every(r=>r.h===140));
    const saved=C.parseFile(C.serializeFile(h.app.dataDocument())).items[0];assert.equal(saved.trackH,after.trackH);assert.equal(saved.trackY,after.trackY);
    h.app.onMove({clientX:0,clientY:0});assert.equal(h.app.trackBox(h.app.state.items[0]).height,bounds.height);
    h.app.stopDrag();h.app.undo();assert.equal(h.app.snapshot(),before);
  }
});
