  h.app.onHeightKey({key:'ArrowDown',preventDefault(){},stopPropagation(){},currentTarget:{dataset:{id:it.id,mode:'bottom'}}});assert.equal(h.app.trackBox(h.app.state.items[0]).bottom,g.max);
