test('Height drag snaps to lanes with magnet and always catches at row boundaries',()=>{const h=make();const it=h.app.state.items.find(i=>h.app.boxKind(i.kind));const g={id:it.id,mode:'bottom',...h.app.heightBounds(it)};const r0=g.rows[0],laneH=h.app.laneH();h.app.state.cfg.magnet=true;assert.equal(h.app.snapEdge(r0.top+laneH-6+5,'bottom',g.rows),r0.top+laneH-6);assert.equal(h.app.snapEdge(r0.top+6+3,'top',g.rows),r0.top+6);h.app.state.cfg.magnet=false;assert.equal(h.app.snapEdge(r0.bottom-6+5,'bottom',g.rows),r0.bottom-6);assert.equal(h.app.snapEdge(r0.top+laneH+3,'bottom',g.rows),r0.top+laneH+3);});
