  step('s',.25);assert.equal(dates()[0],'2028-02-29');step('s',.25);assert.equal(dates()[0],'2028-03-01');step('s',-.25);assert.equal(dates()[0],'2028-02-29');h.app.undo();assert.equal(dates()[0],'2028-03-01');h.app.state.sel=it.id;
  h.app.onPropertyTimeField({currentTarget:{dataset:{field:'e'},value:'2028-03-02'}});assert.equal(dates()[1],'2028-03-02');step('e',-.25);assert.equal(dates()[1],'2028-03-02','range cannot fall below one day');
