test('Expanded palette adds four lightness variants per base hue and keeps picked colours through undo and save',()=>{
  const h=make(),it=h.app.state.items[0];h.app.state.sel=it.id;const base=h.app.renderVals().palette;assert.equal(base.length,9);h.app.togglePalette();const expanded=h.app.renderVals().palette;assert.equal(expanded.length,45);
  const hsl=hex=>{const c=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255),max=Math.max(...c),min=Math.min(...c),d=max-min,l=(max+min)/2;let hue=0;if(d){hue=max===c[0]?((c[1]-c[2])/d)%6:max===c[1]?(c[2]-c[0])/d+2:(c[0]-c[1])/d+4;hue=(hue*60+360)%360;}return {h:hue,s:d?d/(1-Math.abs(2*l-1)):0,l};};
  base.forEach((b,col)=>{const original=hsl(b.hex),colours=[b.hex];for(let row=1;row<5;row++){const hex=expanded[row*9+col].hex,tone=hsl(hex);colours.push(hex);assert.ok(Math.min(Math.abs(tone.h-original.h),360-Math.abs(tone.h-original.h))<(original.s<.15?6:2));assert.ok(Math.abs(tone.s-original.s)<.025);assert.ok(row<3?tone.l<original.l:tone.l>original.l);}assert.equal(new Set(colours).size,5);});
  const colour=expanded[20].hex;h.app.onColor({currentTarget:{dataset:{color:colour}}});assert.equal(C.parseFile(C.serializeFile(h.app.dataDocument())).items[0].color,colour);h.app.togglePalette();assert.equal(h.app.renderVals().palette.length,9);h.app.undo();assert.equal(h.app.state.items[0].color,it.color);
});

